param([string]$Destination=(Join-Path $PSScriptRoot 'DemoProject'))
$ErrorActionPreference='Stop';$utf8=[Text.UTF8Encoding]::new($false)
$a=Join-Path $Destination 'Assets';$sc=Join-Path $a 'Scenes';$ss=Join-Path $a 'Scripts';$set=Join-Path $Destination 'ProjectSettings'
[IO.Directory]::CreateDirectory($sc)|Out-Null;[IO.Directory]::CreateDirectory($ss)|Out-Null;[IO.Directory]::CreateDirectory($set)|Out-Null
Copy-Item (Join-Path $PSScriptRoot 'Assets/Sprites') $a -Recurse -Force;Copy-Item (Join-Path $PSScriptRoot 'Assets/Sounds') $a -Recurse -Force
function J($p,$v){[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 40 -Compress),$utf8)}
$lines=[IO.File]::ReadAllLines((Join-Path $PSScriptRoot 'README.md'),[Text.Encoding]::UTF8);$blocks=[Collections.Generic.List[string]]::new();$inside=$false;$cur=[Collections.Generic.List[string]]::new()
foreach($line in $lines){if(!$inside-and$line-eq'```lua'){$inside=$true;$cur=[Collections.Generic.List[string]]::new()}elseif($inside-and$line-eq'```'){$blocks.Add(($cur-join"`n"));$inside=$false}elseif($inside){$cur.Add($line)}}
$main=$blocks[1..19]-join"`n`n";[IO.File]::WriteAllText((Join-Path $ss 'AshenVale.lua'),$main,$utf8)
$g=@{script='34000000-0000-4000-8000-000000000001';world='34000000-0000-4000-8000-000000000002';ui='34000000-0000-4000-8000-000000000003';title='34000000-0000-4000-8000-000000000004';menu='34000000-0000-4000-8000-000000000005'}
J (Join-Path $ss 'AshenVale.lua.meta') @{schema=1;guid=$g.script;type='Script';importSettings=@{}}
function Slice($n,$x,$y,$w,$h){@{name=$n;rect=@($x,$y,$w,$h);pivot=@(.5,.5);border=@(0,0,0,0)}}
function Tex($n,$guid,$ppu,$s=$null){$i=@{pixelsPerUnit=$ppu;pivotMode='Center';customPivot=@(.5,.5);filterMode='Point';wrapMode='Clamp';alphaIsTransparency=$true;border=@(0,0,0,0);spriteMode=if($s){'Multiple'}else{'Single'}};if($s){$i.spriteSheet=@{sprites=$s}};J ((Join-Path $a "Sprites/$n")+'.meta') @{schema=1;guid=$guid;type='Texture';importSettings=$i}}
$world=@((Slice 'town_floor' 135 0 150 128),(Slice 'dungeon_floor' 285 0 150 128),(Slice 'dungeon_wall' 435 0 140 128),(Slice 'hero_idle' 575 0 112 128),(Slice 'warden' 0 128 120 128),(Slice 'crawler' 450 128 115 128),(Slice 'brute' 680 128 115 128),(Slice 'portal' 910 128 114 128),(Slice 'loot' 900 256 124 128))
$ui=@((Slice 'hp_back' 0 0 190 128),(Slice 'hp_fill' 0 0 190 128),(Slice 'mp_back' 190 0 190 128),(Slice 'mp_fill' 190 0 190 128),(Slice 'panel' 380 0 96 128),(Slice 'slot' 380 0 96 128),(Slice 'skill_might' 476 0 96 128),(Slice 'skill_focus' 572 0 96 128),(Slice 'skill_vigor' 668 0 96 128))
$menu=@((Slice 'title_new' 65 105 760 305),(Slice 'title_load' 65 535 760 305),(Slice 'title_exit' 65 990 760 305),(Slice 'menu_cursor' 315 1375 260 290))
Tex 'world_atlas.png' $g.world 64 $world;Tex 'ui_atlas.png' $g.ui 64 $ui;Tex 'title_background.png' $g.title 128;Tex 'menu_labels.png' $g.menu 128 $menu
J (Join-Path $set 'project.json') @{schema=1;name='AshenValeDemo';version='0.1.0';mainScene='Scenes/Title.nscene';sortingLayers=@('Background','Ground','Actors','Effects','UI')}
function T($x,$y,$sx=1,$sy=1){@{type='Transform';position=@($x,$y,0);rotation=0;scale=@($sx,$sy,1)}}
function S($guid,$sub='',$layer='Actors',$order=0,$size=@(1,1),$color=@(1,1,1,1)){@{type='SpriteRenderer';sprite=$guid;subSprite=$sub;color=$color;flipX=$false;flipY=$true;drawMode='Simple';size=$size;customQuad=$false;quadTL=@(-.5,.5);quadTR=@(.5,.5);quadBR=@(.5,-.5);quadBL=@(-.5,-.5);uvRect=@(0,0,1,1);sortingLayer=$layer;orderInLayer=$order}}
function NewScene($name){$script:ents=@();$script:id=1}
function E($n,$c,$on=$true,$parent=0){$v=$script:id;$script:id++;$script:ents+=,@{id=$v;name=$n;enabled=$on;parent=$parent;components=$c}}
function SaveScene($name,$guid){J (Join-Path $sc "$name.nscene") @{schema=1;sceneName=$name;nextId=$id;entities=$ents};J (Join-Path $sc "$name.nscene.meta") @{schema=1;guid=$guid;type='Scene';importSettings=@{}}}
function HUD($cameraId){E 'HpBack' @((T -5.5 6.3),(S $g.ui 'hp_back' 'UI' 100 @(3.8,.35))) $true $cameraId;E 'HpFill' @((T -5.5 6.3),(S $g.ui 'hp_fill' 'UI' 101 @(3.6,.28))) $true $cameraId;E 'MpBack' @((T -5.5 5.8),(S $g.ui 'mp_back' 'UI' 100 @(3.8,.35))) $true $cameraId;E 'MpFill' @((T -5.5 5.8),(S $g.ui 'mp_fill' 'UI' 101 @(3.6,.28))) $true $cameraId;E 'HelpPanel' @((T 4.8 -6),(S $g.ui 'panel' 'UI' 100 @(3,1))) $true $cameraId}

NewScene 'Title';E 'TitleCamera' @((T 0 0),@{type='Camera';zoom=48;priority=10});E 'TitleBackground' @((T 0 0 1.55 2.2),(S $g.title '' 'Background' -20));E 'NewGameLabel' @((T 0 1 1 .55),(S $g.menu 'title_new' 'UI' 20));E 'LoadGameLabel' @((T 0 0 1 .55),(S $g.menu 'title_load' 'UI' 20));E 'ExitLabel' @((T 0 -1 1 .55),(S $g.menu 'title_exit' 'UI' 20));E 'MenuCursor' @((T -3.7 1 .45 .45),(S $g.menu 'menu_cursor' 'UI' 30));E 'LoadUnavailable' @((T 3 0),(S $g.ui 'slot' 'UI' 25 @(1,.7))) $false;E 'TitleController' @((T 0 0),@{type='Script';script=$g.script;entryFunction='Title'});SaveScene 'Title' '34000000-0000-4000-8000-999999999991'

NewScene 'Town';E 'TownCamera' @((T 0 0),@{type='Camera';zoom=48;priority=10});for($y=1;$y-le16;$y++){for($x=1;$x-le16;$x++){$ix=$x-$y;$iy=($x+$y)*.5;E "TownTile${x}_${y}" @((T $ix $iy),(S $g.world 'town_floor' 'Ground' ($x+$y) @(2,1)))}};E 'Player' @((T 0 0),(S $g.world 'hero_idle' 'Actors' 50 @(1.2,1.7)));E 'WardenNPC' @((T 0 0),(S $g.world 'warden' 'Actors' 40 @(1.2,1.7)));E 'TownPortal' @((T 0 0),(S $g.world 'portal' 'Effects' 45 @(1.4,1.8)));HUD 1;E 'QuestMarker' @((T 0 0),(S $g.ui 'skill_focus' 'UI' 110 @(.45,.45))) $true 1;E 'TownController' @((T 0 0),@{type='Script';script=$g.script;entryFunction='Town'});SaveScene 'Town' '34000000-0000-4000-8000-999999999992'

NewScene 'Dungeon';E 'DungeonCamera' @((T 0 0),@{type='Camera';zoom=48;priority=10});for($i=1;$i-le160;$i++){E ("Floor{0:D3}"-f$i) @((T 0 0),(S $g.world 'dungeon_floor' 'Ground' 0 @(2,1))) $false};for($i=1;$i-le100;$i++){E ("Wall{0:D3}"-f$i) @((T 0 0),(S $g.world 'dungeon_wall' 'Ground' 1 @(2,2))) $false};for($i=1;$i-le16;$i++){E ("Enemy{0:D2}"-f$i) @((T 0 0),(S $g.world 'crawler' 'Actors' 20 @(.8,1.2))) $false};for($i=1;$i-le12;$i++){E ("Loot{0:D2}"-f$i) @((T 0 0),(S $g.world 'loot' 'Effects' 30 @(.4,.4))) $false};E 'DungeonExit' @((T 0 0),(S $g.world 'portal' 'Effects' 40 @(1.4,1.8)));E 'Player' @((T 0 0),(S $g.world 'hero_idle' 'Actors' 50 @(1.2,1.7)));HUD 1;E 'DungeonController' @((T 0 0),@{type='Script';script=$g.script;entryFunction='Dungeon'});SaveScene 'Dungeon' '34000000-0000-4000-8000-999999999993'
Write-Host "Ashen Vale demo created: $Destination"
